INSERT INTO ec_blog_posts (id, slug, status, created_at, updated_at, published_at, version, locale, title, meta_title, meta_description, displayed_publish_date, displayed_tags, content)
SELECT 'holiday-gatherings-20261117', 'hearing-loss-holiday-gatherings', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, 'en', 'Hearing at Holiday Gatherings', 'Hearing at Holiday Gatherings | New Leaf Hearing Care', 'Hard to hear at family dinner? How to set up the room, pick a seat, prep your hearing aids, and know when a hearing test is the next step.', 'November 17, 2026', 'Hearing and Communication', '[{"_type":"block","_key":"holiday1","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday1s0","text":"A full holiday table is the hardest listening environment most people face all year, and struggling there doesn''t mean you''re imagining things. Twelve voices, overlapping sentences, music behind it all, a hard floor bouncing sound around the room: that combination defeats hearing that works fine one-on-one. The fixes below are practical and most of them cost nothing. Where to sit, how to shape the room, what your family can do, and how to tell when the real answer is a hearing test rather than another seat change.","marks":[]}]},{"_type":"block","_key":"holiday2","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"holiday2s0","text":"Why a full room is the hardest listening of the year","marks":[]}]},{"_type":"block","_key":"holiday3","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday3s0","text":"Noise doesn''t just make speech quieter, it makes speech harder to separate. Your brain pulls one voice out of a crowd by tracking small timing and pitch differences between what each ear picks up. When a dozen people talk at once in a room with bare walls, wood floors, and a long table, those differences blur. Add a kitchen fan, a football game, and a playlist, and the voice you want is buried in sound that looks a lot like it.","marks":[]}]},{"_type":"block","_key":"holiday4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday4s0","text":"Distance works against you too. The person across a wide table is two or three times farther away than the person beside you, and every step back drops their voice while the room noise stays put. That''s why the same hearing that handled a quiet coffee last Tuesday feels broken at dinner.","marks":[]}]},{"_type":"block","_key":"holiday5","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"holiday5s0","text":"Where to sit and how to set the room up","marks":[]}]},{"_type":"block","_key":"holiday6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday6s0","text":"Take a seat with your back to a wall, with the most people you want to hear on the side of your better ear. A few more choices that change what you hear:","marks":[]}]},{"_type":"block","_key":"holiday7","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday7s0","text":"Sit at the middle of a long table rather than either end, so nobody is more than a couple of seats away.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday8s0","text":"Keep the brightest light on faces, not behind them. Seeing lips and expressions does real work for understanding.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday9","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday9s0","text":"Put your back to the loudest thing in the room (the kitchen, the speaker, the TV) so your ears face the conversation.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday10","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday10s0","text":"Soften the room before guests arrive. A tablecloth, a rug under the table, and curtains drawn across a big window cut the echo that smears speech. Rooms with nothing soft in them are the ones people leave early.","marks":[]}]},{"_type":"block","_key":"holiday11","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"holiday11s0","text":"What the host and family can do","marks":[]}]},{"_type":"block","_key":"holiday12","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday12s0","text":"Most of the burden belongs to the room and the group, not the person asking \"what?\" Hosts can make a gathering listenable with a handful of decisions:","marks":[]}]},{"_type":"block","_key":"holiday13","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday13s0","text":"Turn the music off during the meal, or down to a level where you can''t make out the lyrics.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday14","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday14s0","text":"Seat the quietest talkers and the children near the people who want to hear them.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday15","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday15s0","text":"Spread conversation across two smaller rooms instead of one loud one.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday16","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday16s0","text":"Get someone''s attention before starting a sentence, and repeat a missed line with different words rather than the same words louder.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday17","style":"normal","markDefs":[{"_key":"holiday17link0","_type":"link","href":"https://newleafhearing.com/audiology-services/communication-training-program/"}],"children":[{"_type":"span","_key":"holiday17s0","text":"Those habits are teachable, and they''re worth saying out loud at the start of the day rather than hoping everyone guesses. If keeping up in noise is a year-round frustration and not a once-a-December problem, our ","marks":[]},{"_type":"span","_key":"holiday17s1","text":"communication training","marks":["holiday17link0"]},{"_type":"span","_key":"holiday17s2","text":" work with patients builds exactly these strategies into everyday conversation so the whole household uses them.","marks":[]}]},{"_type":"block","_key":"holiday18","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"holiday18s0","text":"Service and charge your hearing aids before the first gathering","marks":[]}]},{"_type":"block","_key":"holiday19","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday19s0","text":"Handle hearing aid upkeep the week before the holidays, not the morning of. Wax and moisture build up slowly, and a device that sounds a little dull in a quiet house will sound much worse in a noisy one. Before your first gathering:","marks":[]}]},{"_type":"block","_key":"holiday20","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday20s0","text":"Clean the domes or earmolds and check the wax filters, replacing any that look blocked.","marks":[]}],"listItem":"number","level":1},{"_type":"block","_key":"holiday21","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday21s0","text":"Charge rechargeable aids overnight, and pack spare batteries if yours take them.","marks":[]}],"listItem":"number","level":1},{"_type":"block","_key":"holiday22","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday22s0","text":"Try the noise or speech-in-noise program at home so you''re not learning the buttons at the table.","marks":[]}],"listItem":"number","level":1},{"_type":"block","_key":"holiday23","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday23s0","text":"Pair your phone or any remote microphone accessory you own and confirm it still connects.","marks":[]}],"listItem":"number","level":1},{"_type":"block","_key":"holiday24","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday24s0","text":"Book a clean-and-check with us if anything sounds weak, crackly, or intermittent.","marks":[]}],"listItem":"number","level":1},{"_type":"block","_key":"holiday25","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday25s0","text":"A remote microphone sitting in front of the person across the table is the single biggest improvement many hearing aid wearers get at a holiday meal. If you own one and never use it, this is the week to pull it out.","marks":[]}]},{"_type":"block","_key":"holiday26","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"holiday26s0","text":"Signs it''s time to book a hearing test","marks":[]}]},{"_type":"block","_key":"holiday27","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday27s0","text":"Book a test when the pattern follows you home from the party. Moving seats and turning down music help everyone, so needing them isn''t a diagnosis. Watch instead for the things that don''t resolve:","marks":[]}]},{"_type":"block","_key":"holiday28","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday28s0","text":"You hear people but can''t make out words, and the problem is worst in groups.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday29","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday29s0","text":"You lean on one ear, one side, or one person who \"translates\" for you.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday30","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday30s0","text":"Family turns the TV down after you''ve set it where you want it.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday31","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday31s0","text":"You skip gatherings, or go quiet at them, because following along is exhausting.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday32","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday32s0","text":"Ringing or fullness in your ears lingers after the room empties out.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"holiday33","style":"normal","markDefs":[{"_key":"holiday33link0","_type":"link","href":"https://newleafhearing.com/audiology-services/hearing-assessments/"}],"children":[{"_type":"span","_key":"holiday33s0","text":"A ","marks":[]},{"_type":"span","_key":"holiday33s1","text":"hearing assessment","marks":["holiday33link0"]},{"_type":"span","_key":"holiday33s2","text":" measures where your hearing actually stands and whether speech understanding is holding up alongside the tones. December books up, so scheduling before the season starts gives you time to act on the results instead of waiting until January.","marks":[]}]},{"_type":"block","_key":"holiday34","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"holiday34s0","text":"FAQ","marks":[]}]},{"_type":"block","_key":"holiday35","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"holiday35s0","text":"Why can I hear at home but not at dinner?","marks":[]}]},{"_type":"block","_key":"holiday36","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday36s0","text":"Because quiet rooms do the separating work for you. At home there''s one voice, close by, with no competition. At dinner your ears have to pull one voice out of many at a distance, and that''s the first ability to suffer when hearing changes. Hearing well one-on-one and poorly in a crowd is one of the most common early patterns we see.","marks":[]}]},{"_type":"block","_key":"holiday37","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"holiday37s0","text":"Does turning the music down help?","marks":[]}]},{"_type":"block","_key":"holiday38","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday38s0","text":"Yes, more than almost anything else a host can do. Background music sits in the same pitch range as speech, so it competes directly with the voices you''re trying to follow. Off during the meal is better than low, and low is far better than loud.","marks":[]}]},{"_type":"block","_key":"holiday39","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"holiday39s0","text":"Should I book a hearing test before December?","marks":[]}]},{"_type":"block","_key":"holiday40","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday40s0","text":"Book before the season if you''re already noticing trouble. A test takes one appointment, and knowing your results beforehand means any plan (device adjustments, a new fitting, communication strategies) is in place while the gatherings are still ahead of you.","marks":[]}]},{"_type":"block","_key":"holiday41","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"holiday41s0","text":"Will sitting in the quietest corner solve it?","marks":[]}]},{"_type":"block","_key":"holiday42","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"holiday42s0","text":"It helps for one conversation and costs you the rest of the room. Seat and room changes are worth making, but if you''re building your whole evening around avoiding noise, that''s a signal to get your hearing measured rather than a strategy to keep refining.","marks":[]}]}]'
WHERE NOT EXISTS (SELECT 1 FROM ec_blog_posts WHERE slug = 'hearing-loss-holiday-gatherings');

